using System;
using BepInEx.Configuration;
using EFT;
using EFT.InventoryLogic;
using Il2CppInterop.Runtime.InteropTypes.Arrays;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class DamagePreview {
 static ConfigEntry<bool> enabled=null!;static readonly Il2CppStructArray<RaycastHit> hits=new(128);static float nextRead,nextError;static IntPtr world;static string text="",detail="";static bool lethal;static Player? observed;static GUIStyle? label;
 internal static void Initialize(){enabled=FeatureConfig.Bind("40. 弹道与伤害预览","Damage preview","准星 AI 伤害预览",true,"显示当前弹药的伤害上限与命中部位；可能致死时标红。距离衰减、散布、碎片、护甲和随机穿透会影响实际结果。");}
 internal static void Reset(){text=detail="";world=IntPtr.Zero;nextRead=0;observed=null;}
 static Player? Actor(GameWorld current,string id){var all=current.AllAlivePlayersList;if(all!=null)for(int i=0;i<all.Count;i++){var actor=all[i];if(actor!=null&&actor.ProfileId==id&&!actor.IsYourPlayer&&actor.IsAI&&actor.HealthController?.IsAlive==true)return actor;}return null;}
 static void Read(GameWorld current,Player local,Camera camera){if(world!=current.Pointer){Reset();world=current.Pointer;}if(Time.unscaledTime<nextRead)return;nextRead=Time.unscaledTime+.1f;text=detail="";observed=null;var controller=local.HandsController?.TryCast<Player.FirearmController>();if(controller==null||controller._isInventoryOpened)return;var ammo=MagazineDisplay.CurrentAmmo(local);if(ammo==null)return;var ray=camera.ScreenPointToRay(new Vector3(Screen.width*.5f,Screen.height*.5f));int count=Physics.RaycastNonAlloc(ray.origin,ray.direction,hits,2000,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Collide);if(count>=hits.Length)return;float best=float.MaxValue;BodyPartCollider? body=null;RaycastHit contact=default;bool blocked=false;
  for(int i=0;i<count;i++){var hit=hits[i];var collider=hit.collider;if(collider==null||hit.distance>=best||collider.transform.IsChildOf(local.transform))continue;var part=collider.GetComponent<BodyPartCollider>();if(part!=null&&part.PlayerProfileID==local.ProfileId)continue;if(part==null&&(collider.isTrigger||current.PlayersColliders?.ContainsKey(collider)==true))continue;best=hit.distance;body=part;contact=hit;blocked=part==null;}if(blocked||body==null)return;var target=Actor(current,body.PlayerProfileID);var health=target?.ActiveHealthController;if(target==null||health==null)return;observed=target;var partType=body.BodyPartType;float total=health.GetBodyPartHealth(EBodyPart.Common,false).Current,partHealth=health.GetBodyPartHealth(partType,false).Current;bool immune=Plugin.DamageBlocked(health);float upper=immune?0:DamagePreviewRules.Upper(ammo.Damage,AiActorControl.PreviewDamageFactor(target),total,health.DamageCoeff,health.DamageMultiplier);bool armor=target.TryGetArmorResistData(body,ammo.PenetrationPower,out var resistance);float chance=armor?resistance.GetPenetrationChance(ammo.PenetrationPower):1;float chanceScale=armor&&ArmorResistanceData.MAX_CHANCE>1?100:1;chance=chanceScale>0?Math.Clamp(chance/chanceScale,0,1):0;lethal=!immune&&DamagePreviewRules.PotentiallyLethal(partType is EBodyPart.Head or EBodyPart.Chest,partHealth,total,upper);
  text=immune?"预计 0 · AI 无敌":(armor?"预计 0–":"预计 ≤ ")+upper.ToString("0.#")+" · "+Part(partType)+(lethal?" · 可能致死":"");detail=(ammo.ProjectileCount>1?"单弹丸 · ":"")+(armor?"穿透 "+(chance*100).ToString("0.#")+"% · ":"")+"部位生命 "+partHealth.ToString("0.#")+" · "+Vector3.Distance(local.Position,contact.point).ToString("F0")+" 米";
 }
 static string Part(EBodyPart part)=>part switch{EBodyPart.Head=>"头部",EBodyPart.Chest=>"胸部",EBodyPart.Stomach=>"腹部",EBodyPart.LeftArm=>"左臂",EBodyPart.RightArm=>"右臂",EBodyPart.LeftLeg=>"左腿",EBodyPart.RightLeg=>"右腿",_=>"全身"};
 internal static void Draw(GameWorld current,Player local,Camera camera,GUIStyle source){if(!enabled.Value||InterfaceMenu.Open||Cursor.visible){text="";return;}try{Read(current,local,camera);if(text.Length==0||observed?.HealthController?.IsAlive!=true)return;label??=new GUIStyle(source){alignment=TextAnchor.UpperCenter,wordWrap=false,richText=false};label.fontSize=14;var rect=new Rect(Screen.width*.5f-240,Screen.height*.5f+22,480,48);var color=GUI.color;GUI.color=Color.black;GUI.Label(new Rect(rect.x+1,rect.y+1,rect.width,rect.height),text+"\n"+detail,label);GUI.color=lethal?new Color(1,.2f,.2f):new Color(1,.92f,.63f);GUI.Label(rect,text+"\n"+detail,label);GUI.color=color;}catch(Exception e){text="";if(Time.unscaledTime>=nextError){nextError=Time.unscaledTime+20;Plugin.Self.Log.LogWarning("Damage preview: "+e.Message);}}}
}
